'use strict';

function createDocumentIndex(input) {
  if (!Array.isArray(input)) throw new TypeError('input must be an array');
  const seen = new Set();
  const records = input.map(record => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) throw new TypeError('invalid record');
    if (typeof record.code !== 'string' || record.code.trim() === '' || typeof record.title !== 'string' || record.title.trim() === '' || typeof record.state !== 'string' || record.state.trim() === '' || !Array.isArray(record.labels) || record.labels.some(label => typeof label !== 'string')) throw new TypeError('invalid record');
    if (seen.has(record.code)) throw new RangeError('duplicate code');
    seen.add(record.code);
    return { code: record.code, title: record.title, state: record.state, labels: record.labels.slice() };
  });
  const clone = record => ({ code: record.code, title: record.title, state: record.state, labels: record.labels.slice() });
  const paginate = (source, page, size) => {
    if (!Number.isInteger(page) || page < 1 || !Number.isInteger(size) || size < 1) throw new TypeError('invalid pagination');
    const start = (page - 1) * size;
    return { items: source.slice(start, page * size + size).map(clone), page, size, total: source.length };
  };
  return {
    page(number, size) { return paginate(records, number, size); },
    lookup(code) {
      if (typeof code !== 'string' || code.trim() === '') throw new TypeError('invalid code');
      const record = records.find(item => item.code === code);
      return record ? clone(record) : null;
    },
    byState(state, number, size) {
      if (typeof state !== 'string' || state.trim() === '') throw new TypeError('invalid state');
      return paginate(records.filter(item => item.state === state), number, size);
    },
    search(text, number, size) {
      if (typeof text !== 'string') throw new TypeError('invalid text');
      const query = text.toLowerCase();
      return paginate(records.filter(item => item.title.toLowerCase().includes(query)), number, size);
    }
  };
}

module.exports = { createDocumentIndex };

