'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['createDocumentIndex']);
const { createDocumentIndex } = api;

assert.throws(() => createDocumentIndex(), TypeError);
assert.throws(() => createDocumentIndex(null), TypeError);
assert.throws(() => createDocumentIndex([{ code: 'A', title: 'One', state: 'new', labels: [] }, { code: 'A', title: 'Two', state: 'old', labels: [] }]), RangeError);
for (const bad of [
  null,
  [],
  { code: '', title: 'T', state: 'S', labels: [] },
  { code: 'C', title: '', state: 'S', labels: [] },
  { code: 'C', title: 'T', state: '', labels: [] },
  { code: 'C', title: 'T', state: 'S', labels: 'x' },
  { code: 'C', title: 'T', state: 'S', labels: [1] }
]) assert.throws(() => createDocumentIndex([bad]), TypeError);

const empty = createDocumentIndex([]);
assert.deepStrictEqual(empty.page(1, 10), { items: [], page: 1, size: 10, total: 0 });
assert.strictEqual(empty.lookup('missing'), null);

const records = [
  { code: 'A1', title: 'Alpha Guide', state: 'draft', labels: ['guide', ''] },
  { code: 'B2', title: 'Beta ALPHA Notes', state: 'published', labels: ['notes'] },
  { code: 'C3', title: 'Gamma', state: 'draft', labels: [] },
  { code: 'D4', title: 'Delta', state: 'draft', labels: ['final'] }
];
const original = JSON.parse(JSON.stringify(records));
const index = createDocumentIndex(records);
assert.deepStrictEqual(records, original);
records[0].title = 'mutated';
records[0].labels.push('mutated');

assert.deepStrictEqual(index.page(1, 2), { items: original.slice(0, 2), page: 1, size: 2, total: 4 });
assert.deepStrictEqual(index.page(2, 2), { items: original.slice(2, 4), page: 2, size: 2, total: 4 });
assert.deepStrictEqual(index.page(3, 2), { items: [], page: 3, size: 2, total: 4 });
assert.deepStrictEqual(index.byState('draft', 1, 2), { items: [original[0], original[2]], page: 1, size: 2, total: 3 });
assert.deepStrictEqual(index.byState('draft', 2, 2), { items: [original[3]], page: 2, size: 2, total: 3 });
assert.deepStrictEqual(index.byState('Draft', 1, 10), { items: [], page: 1, size: 10, total: 0 });
assert.deepStrictEqual(index.search('alpha', 1, 10), { items: [original[0], original[1]], page: 1, size: 10, total: 2 });
assert.deepStrictEqual(index.search('ALPHA', 1, 1), { items: [original[0]], page: 1, size: 1, total: 2 });
assert.deepStrictEqual(index.search('', 2, 3), { items: [original[3]], page: 2, size: 3, total: 4 });
assert.deepStrictEqual(index.lookup('B2'), original[1]);
assert.strictEqual(index.lookup('b2'), null);

const lookup1 = index.lookup('A1');
const lookup2 = index.lookup('A1');
assert.notStrictEqual(lookup1, lookup2);
assert.notStrictEqual(lookup1.labels, lookup2.labels);
lookup1.title = 'changed';
lookup1.labels.push('changed');
assert.deepStrictEqual(index.lookup('A1'), original[0]);
const result = index.page(1, 1);
result.items[0].labels.push('changed');
result.items[0].state = 'changed';
assert.deepStrictEqual(index.lookup('A1'), original[0]);

for (const args of [[0, 1], [-1, 1], [1.5, 1], [1, 0], [1, -1], [1, 1.5], ['1', 1], [1, '1']]) {
  assert.throws(() => index.page(...args), TypeError);
}
for (const bad of [undefined, null, '', 1]) assert.throws(() => index.lookup(bad), TypeError);
for (const bad of [undefined, null, '', 1]) assert.throws(() => index.byState(bad, 1, 1), TypeError);
for (const bad of [undefined, null, 1]) assert.throws(() => index.search(bad, 1, 1), TypeError);
assert.throws(() => index.byState('draft', 0, 1), TypeError);
assert.throws(() => index.search('a', 1, 0), TypeError);

